globalThis.KENGURU_GRADES_5_6 = [{"year":2025,"id":"2025-5-6","grades":[5,6],"label":"5–6 классы","tasksUrl":"assets/kenguru/kenguru_2025_class_5-6.pdf","answersUrl":"assets/kenguru/kenguru_2025_answers.pdf","solutionUrl":"assets/kenguru/kenguru_2025_solution.pdf","cards":[[840,133,1],[841,131,1],[840,184,4],[840,107,1],[856,203,1],[849,115,2],[840,197,0],[849,142,1],[845,109,2],[841,160,1],[841,132,1],[841,131,3],[840,182,0],[841,140,3],[844,203,3],[846,165,2],[824,172,2],[846,161,4],[846,149,1],[838,213,0],[837,143,4],[837,120,1],[841,109,4],[825,159,3],[840,182,2],[841,176,0],[841,191,2],[842,167,3],[827,118,3],[841,131,3]]}];
globalThis.KENGURU_GRADE_CONDITIONS = {"2025":{"1":{"question":"Какой из кусочков мозаики должен находиться на месте, отмеченном знаком вопроса, чтобы узор был подобран верно?","image":"assets/grade-conditions/2025/task-01.webp","imageWidth":678,"imageHeight":288},"2":{"question":"Аня построила из кубиков конструкцию, в которой тёмными кубиками выложила число 2025, как на картинке справа. Вика стоит позади этой конструкции. Что видит Вика?","image":"assets/grade-conditions/2025/task-02.webp","imageWidth":1036,"imageHeight":152},"3":{"question":"У Миши есть билет с числами в центральной части и отверстиями в серых закрылках по обеим сторонам, как показано на рисунке. Он складывает правый закрылок по пунктирной линии и через отверстия видит числа 2, 3, 5 и 6. После этого он также складывает по пунктирной линии левый закрылок. Какова сумма чисел, которые он теперь видит через отверстия?","choices":["10","12","14","9","8"],"image":"assets/grade-conditions/2025/task-03.webp","imageWidth":282,"imageHeight":128},"4":{"question":"Белый куб украсили, наклеив на него одинаковые серые квадраты. Все грани куба получились одинаковыми. Сколько серых квадратов использовано?","choices":["30","18","16","15","14"],"image":"assets/grade-conditions/2025/task-04.svg","imageWidth":220,"imageHeight":217},"5":{"question":"Вадим положил на пиццу кусочки помидоров, маслины, перец чили, грибы и луковые кольца, но не обязательно в этом порядке. За один раз он раскладывал только какую-то одну начинку. Его пицца показана на рисунке. Какую начинку он положил третьей по очереди?","image":"assets/grade-conditions/2025/task-05.webp","imageWidth":792,"imageHeight":380},"6":{"question":"В сосуде A находится 10 литров воды. Все пять пробок на дне этого сосуда вынимают одновременно, и вода начинает вытекать. Какой объём воды попадёт в контейнер B?","choices":["3 литра","4 литра","5 литров","6 литров","8 литров"],"image":"assets/grade-conditions/2025/task-06.webp","imageWidth":269,"imageHeight":210},"7":{"question":"Таня вращает шестиугольник, разделённый на шесть равных частей. При каждом повороте фигура поворачивается на одну часть по часовой стрелке. Изначальное положение и результат одного поворота показаны на рисунке. Как будет выглядеть шестиугольник после восьми поворотов?","image":"assets/grade-conditions/2025/task-07.webp","imageWidth":1010,"imageHeight":221},"8":{"question":"Дождь смыл некоторые цифры с цен в меню. Бургеры перечислены от самого дешёвого до самого дорогого. В этом порядке видны цены 370, □30, □60, □50, □10 и 680 рублей. Каждый квадрат закрывает одну цифру. Какая из предложенных цен есть в меню?","choices":["410 руб.","550 руб.","560 руб.","630 руб.","660 руб."],"image":"assets/grade-conditions/2025/task-08.webp","imageWidth":253,"imageHeight":263},"9":{"question":"В забеге приняли участие шесть детей. Арина заняла третье место. Боря занял шестое место, сразу за Мишей. Юля оказалась между Ариной и Мишей. Диана обогнала Федю прямо перед финишем. Кто выиграл забег?","choices":["Арина","Федя","Диана","Миша","Юля"]},"10":{"question":"На стене висят три книжные полки. На верхней из них стоит 17 книг, на средней – 15 книг, а на нижней – 7 книг. Марина хочет, чтобы на всех полках было одинаковое количество книг. Она также хочет переместить как можно меньше книг. Сколько книг ей нужно переместить со средней полки на нижнюю?","choices":["1","2","3","4","5"],"image":"assets/grade-conditions/2025/task-10.webp","imageWidth":286,"imageHeight":164},"11":{"question":"Три кенгуру участвуют в забеге на 10 километров. Каждый из них движется с постоянной скоростью. Когда первый кенгуру финишировал, второй кенгуру преодолел четверть дистанции, а третий – одну пятую дистанции. На каком расстоянии от финиша будет находиться третий кенгуру, когда финиширует второй?","choices":["1 км","2 км","3 км","4 км","5 км"]},"12":{"question":"Вера построила башню из блоков. Она хочет заменить два блока с вопросительными знаками на два блока с числами. При этом она хочет, чтобы число на каждом блоке башни было как минимум на 2 больше, чем число на блоке ниже. Сколькими способами Вера может это сделать?","choices":["3","4","5","6","7"],"image":"assets/grade-conditions/2025/task-12.svg","imageWidth":65,"imageHeight":252},"13":{"question":"На рисунке изображены пять колёс удачи. Каждое колесо разделено на разное количество одинаковых секторов. Для выигрыша нужно, чтобы раскрученное колесо остановилось так, чтобы треугольный указатель над ним указывал на закрашенный сектор. Какое колесо даёт наибольший шанс на победу?","choices":["1","2","3","4","5"],"image":"assets/grade-conditions/2025/task-13.webp","imageWidth":523,"imageHeight":139},"14":{"question":"Какая из следующих фигур ни в каком положении не может быть размещена целиком только на белых участках данного квадрата?","image":"assets/grade-conditions/2025/task-14.webp","imageWidth":915,"imageHeight":272},"15":{"question":"Школьная команда по плаванию участвует в эстафете. Пять пловцов по очереди проплыли одинаковую дистанцию. Тренер фиксировал время, когда каждый из ребят завершал свою часть заплыва (все пять показателей приведены на рисунке). Первый пловец проплыл дистанцию за 2 минуты и 8 секунд. Кто из пловцов затратил на эту дистанцию меньше всего времени?","choices":["Первый","Второй","Третий","Четвёртый","Пятый"],"image":"assets/grade-conditions/2025/task-15.webp","imageWidth":598,"imageHeight":119},"16":{"question":"Женя отрезала четыре одинаковых квадрата от углов квадратного листа бумаги, как показано на рисунке. Общая площадь вырезанных частей – 16 см², а площадь оставшегося креста – 9 см². Каков периметр креста в сантиметрах?","choices":["9 см","16 см","20 см","25 см","32 см"],"image":"assets/grade-conditions/2025/task-16.webp","imageWidth":394,"imageHeight":169},"17":{"question":"На каждой из карточек написано по два трёхзначных числа, но некоторые цифры в них закрашены. На одной из карточек сумма цифр обоих чисел одинакова. Какая это карточка?","image":"assets/grade-conditions/2025/task-17.webp","imageWidth":728,"imageHeight":119},"18":{"question":"Фигура на рисунке состоит из одинаковых квадратов. Точка B находится посередине между точками A и C. Точка D находится посередине между точками C и E. Маша хочет разделить эту фигуру на две части равной площади. Какую из точек она должна соединить отрезком с точкой S, чтобы сделать это?","choices":["A","B","C","D","E"],"image":"assets/grade-conditions/2025/task-18.webp","imageWidth":250,"imageHeight":299},"19":{"question":"Юра хочет записать 0 или 1 в каждую ячейку таблицы так, чтобы сумма чисел в каждой строке, столбце и диагонали равнялась 3. Он уже написал 0 в одной из ячеек. Какова будет сумма чисел в ячейках, обозначенных вопросительными знаками, когда он заполнит всю таблицу?","choices":["1","2","3","4","Невозможно посчитать"],"image":"assets/grade-conditions/2025/task-19.svg","imageWidth":219,"imageHeight":220},"20":{"question":"Катя и Лёша записали по три трёхзначных числа, используя цифры от 1 до 9 ровно по одному разу. Затем они записали свои числа слева направо в возрастающем порядке. Например: первое число – 392; второе число – 487; третье число – 516. Оказалось, что Катино второе число – максимально возможное из всех, которые могут быть записаны на втором месте. А Лёшино второе число – минимально возможное из всех чисел, которые могут быть записаны на втором месте. Какова разница между этими числами?","choices":["642","684","864","888","Ни одно из них"]},"21":{"question":"У волшебницы было 10 яблок, 9 бананов и 6 груш. Она превратила каждый из фруктов в один какой-то другой фрукт. Например, каждый банан она превратила либо в яблоко, либо в грушу. Теперь у неё стало 15 яблок, 7 бананов и 3 груши. Сколько яблок она превратила в бананы?","choices":["3","4","5","6","7"]},"22":{"question":"Длина стороны квадрата на рисунке равна 10 см. Каждый из отрезков, проходящих через центр квадрата, делит его на две равные части. Какова площадь закрашенной области?","choices":["12,5 см²","25 см²","30 см²","40 см²","50 см²"],"image":"assets/grade-conditions/2025/task-22.svg","imageWidth":220,"imageHeight":220},"23":{"question":"Саша делит фигуру, изображённую на рисунке, на пять одинаковых частей, каждая из которых состоит из трёх квадратов. Квадрат с какой буквой будет находиться в той же части, что и квадрат, отмеченный звёздочкой?","choices":["A","B","C","D","E"],"image":"assets/grade-conditions/2025/task-23.svg","imageWidth":220,"imageHeight":220},"24":{"question":"Дима никогда не говорит правду по вторникам, четвергам и субботам. В остальные дни недели он всегда говорит правду. Однажды у него состоялся следующий диалог с Матвеем: Матвей: «Какой сегодня день?» Дима: «Суббота». Матвей: «Какой день будет завтра?» Дима: «Среда». В какой день недели произошёл этот разговор?","choices":["Понедельник","Вторник","Среда","Четверг","Пятница"]},"25":{"question":"Лена хочет сложить крест, как на рисунке справа, используя следующие детали. У неё есть много копий каждой детали, и она может поворачивать их при необходимости. Однако детали не должны перекрывать друг друга. Какое минимальное количество деталей ей потребуется, чтобы сложить такой крест?","choices":["11","12","13","15","17"],"image":"assets/grade-conditions/2025/task-25.webp","imageWidth":273,"imageHeight":246},"26":{"question":"Имеется конструкция, которая состоит из разных блоков и находится в состоянии баланса. Блоки с одинаковым рисунком весят одинаково. Витя хочет упорядочить три типа квадратных блоков от самого тяжёлого до самого лёгкого. В каком порядке должны быть расположены блоки?","image":"assets/grade-conditions/2025/task-26.webp","imageWidth":1032,"imageHeight":252},"27":{"question":"Даша хочет заполнить квадраты на рисунке числами от 1 до 9, вписывая по одному числу без повторения в каждый квадрат. Она также хочет, чтобы сумма чисел в любых двух соседних квадратах была равна числу, указанному на линии, соединяющей эти квадраты. Какова сумма чисел, которые она должна вписать в закрашенную строку?","choices":["16","17","18","20","21"],"image":"assets/grade-conditions/2025/task-27.webp","imageWidth":241,"imageHeight":235},"28":{"question":"Таня строит разные конструкции, соединяя три блока, показанные на рисунке справа. Какую из следующих конструкций она может построить?","image":"assets/grade-conditions/2025/task-28.webp","imageWidth":965,"imageHeight":233},"29":{"question":"У Гены было в три раза больше шоколадок, чем у Серёжи. Гена отдал четверть своих шоколадок Серёже, после чего у него стало на шесть шоколадок больше, чем у Серёжи. На сколько больше шоколадок было у Гены изначально?","choices":["36","30","27","24","20"]},"30":{"question":"Мама выбирает цветы трёх видов по 30, 40 и 50 рублей за цветок. Сколько разных букетов стоимостью ровно 230 рублей она может купить? Букеты различаются количеством цветов каждого вида.","choices":["4","5","6","7","8"],"image":"assets/grade-conditions/2025/task-30.webp","imageWidth":300,"imageHeight":226}}};
globalThis.KENGURU_GRADE_SOLUTION_STEPS = {"2025":{"1":{"steps":[{"text":"Продолжим линии мозаики по обе стороны от серого участка, чтобы соседние плитки состыковались.","image":"assets/grade-solution-steps/2025/task-01-1.svg","imageWidth":366,"imageHeight":201},{"text":"Сравним получившийся рисунок с вариантами. Подходит фрагмент Б."}]},"2":{"steps":[{"text":"Если смотреть на конструкцию с обратной стороны: цифра 5 будет первой и будет читаться как 2, две цифры 2 будут читаться как 5, 0 останется без изменений."},{"text":"Вика увидит 2505."}]},"3":{"steps":[{"text":"Складываем правый закрылок, и видимыми остаются следующие цифры 3, 5, 2 и 6.","image":"assets/grade-solution-steps/2025/task-03-1.svg","imageWidth":192,"imageHeight":126},{"text":"Затем складываем левый закрылок, и после этого видимыми остаются цифры 3 и 5.","image":"assets/grade-solution-steps/2025/task-03-2.svg","imageWidth":102,"imageHeight":126},{"text":"3 + 5 = 8."}]},"4":{"steps":[{"text":"К каждой грани приклеены 1 полный квадрат и 4 половинки квадрата, то есть всего 3 квадрата."},{"text":"У куба 6 граней, значит всего 6 · 3 = 18 квадратов."}]},"5":{"steps":[{"text":"Посмотрим, какие ингредиенты лежат друг на друге. Под луком лежат только помидоры. Под грибами видны маслины и лук."},{"text":"Перец чили лежит поверх грибов и маслин. Получаем порядок снизу вверх: помидоры, лук, маслины, грибы, перец чили."},{"text":"Третьими были маслины."}]},"6":{"steps":[{"text":"Всего в сосуде 10 л."},{"text":"Тогда через каждое отверстие, после того как вынут пробки, вытечет по 10 : 5 = 2 л воды."},{"text":"Таким образом, 6 л попадёт в средний контейнер, 2 л сразу попадут в контейнер (В), и ещё 2 л вытекут через самую правую трубу."},{"text":"Из среднего контейнера выходят две трубы, через каждую из них вытечет 6 : 2 = 3 л воды."},{"text":"Одна из них ведет в контейнер (В)."},{"text":"Тогда всего в контейнер (В) попадёт 3 + 2 = 5 л."}]},"7":{"steps":[{"text":"После 6 поворотов шестиугольник вернётся в исходное положение."},{"text":"Тогда нужно сделать ещё 2 поворота.","image":"assets/grade-solution-steps/2025/task-07-1.svg","imageWidth":423,"imageHeight":90},{"text":"Видим, что итоговое положение соответствует ответу (А)."}]},"8":{"steps":[{"text":"Цена нижней позиции больше верхней."},{"text":"Тогда классический бургер стоит не менее 430 руб., бургер с беконом — не менее 460 руб., бургер с сыром — не менее 550 руб., а двойной бургер — не менее 610 руб."},{"text":"Если бы любой из бургеров был дороже, то бургер делюкс не мог бы стоить 680 руб."},{"text":"Следовательно, цены четырёх бургеров в середине списка составляют 430 руб., 460 руб., 550 руб. и 610 руб."},{"text":"Подходит только ответ Б."}]},"9":{"steps":[{"text":"Из условия мы знаем, что Арина заняла третье место, Миша – пятое, а Боря – шестое."},{"text":"Так как Юля оказалась между Ариной и Мишей, то она могла занять только четвёртое место."},{"text":"Остаются первое и второе места."},{"text":"Диана обогнала Федю, значит она заняла первое место, а Федя второе."},{"text":"Значит, Диана выиграла забег."}]},"10":{"steps":[{"text":"Всего на трёх полках 17 + 15 + 7 = 39 книг."},{"text":"Значит, на каждой полке должно быть 39 : 3 = 13 книг."},{"text":"Переместим 17 – 13 = 4 книги с верхней полки и 15 – 13 = 2 книги со средней полки на нижнюю полку."},{"text":"Так на каждой полке окажется по 13 книг."},{"text":"Со средней полки на нижнюю мы переместили 2 книги."}]},"11":{"steps":[{"text":"Пока второй кенгуру пробегает 1/4 пути, третий пробегает 1/5 пути."},{"text":"Второму кенгуру осталось пробежать 3/4 пути. Это втрое больше расстояния, которое он уже пробежал."},{"text":"За это же время третий кенгуру пробежит ещё 3/5 пути. Ему останется 1 − 1/5 − 3/5 = 1/5 пути."},{"text":"Весь путь составляет 10 км. Осталось пробежать 10 : 5 = 2 км."}]},"12":{"steps":[{"text":"Возможные варианты: 8 и 10, 8 и 11, 8 и 12, 9 и 11, 9 и 12, 10 и 12."},{"text":"Всего 6 вариантов."}]},"13":{"steps":[{"text":"Для каждого колеса разделим число закрашенных секторов на общее число секторов."},{"text":"Для колёс 1, 2, 3, 4 и 5 получим соответственно 2/8, 2/10, 1/6, 2/12 и 1/7."},{"text":"Наибольшее значение — 2/8 = 1/4. Колесо 1 даёт наибольший шанс на победу."}]},"14":{"steps":[{"text":"Попробуем разместить каждую предложенную фигуру на поле, совместив её клетки с подходящими клетками поля.","image":"assets/grade-solution-steps/2025/task-14-1.svg","imageWidth":609,"imageHeight":141},{"text":"На рисунке показано, как разместить фигуры А, Б, В и Д. Для фигуры Г подходящего места нет."}]},"15":{"steps":[{"text":"Первый спортсмен проплыл дистанцию за (2 мин + 8 с), второй – за (2 мин – 1 с), третий – за (2 мин + 3 с), четвёртый – за (2 мин – 5 с) и пятый – за (2 мин – 2 с)."},{"text":"Значит, четвёртый пловец проплыл быстрее всех."}]},"16":{"steps":[{"text":"Площадь исходного листа составляет 16 + 9 = 25 см²."},{"text":"Тогда длина стороны этого квадрата – 5 см, а его периметр равен 4 · 5 = 20 см."},{"text":"Периметр креста такой же."}]},"17":{"steps":[{"text":"На карточке А у числа 543 сумма цифр 12. В числе 11□ недостающая цифра должна быть 10, поэтому А отпадает."},{"text":"На карточке Б сумма цифр 58□ не меньше 13. У числа 11□ она не больше 11. В варианте Г у числа 211 сумма цифр 4, а у 6□□ она не меньше 6."},{"text":"В варианте Д у числа 777 сумма цифр 21, а две недостающие цифры числа 2□□ должны были бы дать в сумме 19. Две цифры дают не больше 18."},{"text":"В варианте В сумма цифр 982 равна 19. Число 199 даёт такую же сумму. Значит, подходит карточка В."}]},"18":{"steps":[{"text":"Заметим, что без двух верхних и двух правых квадратиков фигура превращается в прямоугольник, который делится диагональю SE на два равных треугольника.","image":"assets/grade-solution-steps/2025/task-18-1.svg","imageWidth":249,"imageHeight":297},{"text":"Так как выделенные верхняя и боковая части тоже между собой одинаковы, то этот отрезок делит всю фигуру на две равные по площади фигуры."}]},"19":{"steps":[{"text":"Поскольку 0 уже стоит, все остальные ячейки во второй строке, третьем столбце и диагональ, проходящая через ячейку с 0, должны быть заполнены цифрой 1."},{"text":"Если теперь мы поместим 0 или 1 в какую-либо одну из ячеек с вопросительным знаком и заполним остальные ячейки, увидим, что сумма чисел в ячейках с вопросительными знаками будет равна 2.","image":"assets/grade-solution-steps/2025/task-19-1.svg","imageWidth":552,"imageHeight":165},{"text":"Есть два варианта заполнения таблицы."}]},"20":{"steps":[{"text":"Наибольшее трёхзначное число – то, которое начинается с 9."},{"text":"Но первая цифра во втором числе Кати не может быть 9, так как третье число по условию больше второго."},{"text":"Поэтому её второе число должно начинаться с 8."},{"text":"Если не использовать цифру 9, то максимально возможным из всех чисел, стоящих на втором месте, может быть только 876."},{"text":"Наименьшее трёхзначное число – то, которое начинается с 1."},{"text":"Но первая цифра во втором числе Лёши не может быть 1, так как первое число по условию меньше второго."},{"text":"Поэтому его второе число должно начинаться с 2."},{"text":"Если не использовать цифру 1, то минимально возможным из всех чисел, стоящих на втором месте, может быть только 234."},{"text":"Их разность составляет 876 – 234 = 642."}]},"21":{"steps":[{"text":"Заметим, что бананов и груш изначально 9 + 6 = 15, что в точности равно количеству яблок после превращения."},{"text":"Это означает, что ВСЕ бананы и груши превратились в яблоки."},{"text":"То есть ни один банан не превратился в грушу, потому что тогда из бананов и груш получилось бы меньше 15 яблок."},{"text":"Аналогично, ни одна груша не превратилась в банан."},{"text":"Значит, 10 яблок превратились в 7 бананов и 3 груши."}]},"22":{"steps":[{"text":"Сторона квадрата 10 см, поэтому его площадь 10 · 10 = 100 см²."},{"text":"На рисунке виден большой треугольник площадью в половину квадрата, то есть 50 см². Маленький треугольник занимает четверть квадрата, то есть 25 см².","image":"assets/grade-solution-steps/2025/task-22-1.svg","imageWidth":615,"imageHeight":180},{"text":"Площадь выделенной фигуры равна разности этих площадей: 50 − 25 = 25 см²."}]},"23":{"steps":[{"text":"В крайнем правом столбце нет трёх клеток подряд. Если детали прямые, то каждую клетку этого столбца приходится накрывать горизонтальной полоской из трёх клеток. В таком случае клетку С можно накрыть только горизонтальной полоской во втором ряду. После этого у верхней левой клетки не останется свободных соседей.","title":"Проверим прямые детали","image":"assets/grade-solution-steps/2025/task-23-bars.svg","imageWidth":304,"imageHeight":304,"imageAlt":"Четыре горизонтальные полоски. Левая верхняя клетка изолирована."},{"text":"У крайней правой клетки первого ряда есть только один уголок: с клеткой слева и клеткой С. У верхней левой клетки есть три варианта. Уголок с В и звёздочкой изолирует А. Уголок с А и звёздочкой вынуждает соединить В с двумя левыми клетками третьего ряда, и тогда нижний левый угол останется без детали. Значит, сверху слева один уголок с А и В.","title":"Найдём верхние уголки","image":"assets/grade-solution-steps/2025/task-23-upper.svg","imageWidth":304,"imageHeight":304,"imageAlt":"Два верхних уголка. Слева накрыты А и В, справа накрыта С."},{"text":"У звёздочки осталась свободная соседка только снизу. Клетку под звёздочкой можно соединить с D или с E. Если взять D, две левые клетки нижнего ряда останутся без свободных соседей сверху и не образуют уголок. Значит, со звёздочкой в одной детали находится E.","title":"Найдём деталь со звёздочкой","image":"assets/grade-solution-steps/2025/task-23-star.svg","imageWidth":304,"imageHeight":304,"imageAlt":"Три уголка. Звёздочка и Е накрыты одним уголком."},{"text":"Оставшиеся клетки образуют два отдельных уголка. Вместе с тремя найденными уголками они заполняют всю фигуру. Разбиение единственное. Клетка Е находится в одной детали со звёздочкой.","title":"Проверим разбиение","image":"assets/grade-solution-steps/2025/task-23-1.svg","imageWidth":165,"imageHeight":165}]},"24":{"steps":[{"text":"Два ответа противоречат друг другу, значит диалог происходит в один из дней, когда Дима лжёт (вторник, четверг или суббота)."},{"text":"Следовательно, оба утверждения неверны."},{"text":"И тогда этот диалог не может происходить в субботу или вторник (день перед средой)."},{"text":"Следовательно, единственный возможный день – четверг."}]},"25":{"steps":[{"text":"У креста восемь углов по 45°. Их могут заполнить только детали с острым углом. Ближайшие из этих углов креста разнесены на диагональ квадрата 2 × 2, а любая деталь помещается в прямоугольник 2 × 1. Диагональ такого прямоугольника короче. Поэтому каждый острый угол требует отдельной детали площадью не больше одной клетки.","title":"Отметим восемь острых углов","image":"assets/grade-solution-steps/2025/task-25-corners.svg","imageWidth":384,"imageHeight":384,"imageAlt":"Крест на клетчатой сетке. Отмечены восемь острых углов."},{"text":"В кресте 13 целых клеток и восемь половинок: 13 + 8 : 2 = 17 клеток. Восемь деталей у острых углов закрывают не больше 8 клеток. Остаётся не меньше 17 − 8 = 9 клеток. Площадь самой большой детали — 2 клетки, поэтому на оставшуюся часть нужно ещё не меньше пяти деталей.","title":"Найдём нижнюю границу"},{"text":"Всего нужно не меньше 8 + 5 = 13 деталей. На рисунке показана сборка из тринадцати: восемь деталей по концам креста, четыре прямоугольника и один квадрат в центре. Значит, 13 — минимум.","title":"Покажем сборку","image":"assets/grade-solution-steps/2025/task-25-1.svg","imageWidth":234,"imageHeight":234}]},"26":{"steps":[{"text":"Сравнивая левую и правую стороны всей конструкции, видим, что два блока с точками весят столько же, сколько три блока с крестиком, значит блоки с точками тяжелее."},{"text":"На левой части весов мы видим, что блок с крестиком и блок с линией вместе весят столько же, сколько два блока с точками."},{"text":"Но поскольку мы уже выяснили, что блоки с крестиком легче, чем с точками, то для равновесия блок с линией должен быть тяжелее."},{"text":"Таким образом, правильная последовательность блоков, расположенных по убыванию веса, приведена в ответе A."}]},"27":{"steps":[{"text":"Если сумма двух цифр содержит 1 в качестве слагаемого, то эта сумма всегда будет меньше или равна 10."},{"text":"Тогда у квадрата, содержащего 1, такими будут все суммы, написанные на соединяющих его линиях."},{"text":"Единственный квадрат с таким свойством расположен в нижнем правом углу.","image":"assets/grade-solution-steps/2025/task-27-1.svg","imageWidth":249,"imageHeight":246},{"text":"Поэтому положение 1 определено однозначно."},{"text":"Остальные квадраты легко заполняются числами, исходя из указанных сумм."},{"text":"Сумма чисел в закрашенной строке: 5 + 4 + 9 = 18."}]},"28":{"steps":[{"text":"Проверим каждую из конструкций: (A) – невозможно, потому что по крайней мере один из кубиков в верхней части должен быть из второго блока."},{"text":"Но тогда не получится разместить два других блока так, чтобы получилась такая конструкция."},{"text":"(Б) – невозможно, потому что второй блок «двухэтажный», значит хотя бы один кубик должен возвышаться над конструкцией."},{"text":"(В) – невозможно, потому что кубик в верхней части очевидно относится ко второму блоку, но тогда нет возможности разместить два других блока так, чтобы получилась такая конструкция."},{"text":"(Г) – возможно, так как один кубик из второго блока и один кубик из третьего блока находятся в верхней части конструкции: (Д) – невозможно, потому что в верхней части может быть не более 3 кубиков."}]},"29":{"steps":[{"text":"Пусть у Серёжи сначала было m шоколадок. Тогда у Гены было 3m шоколадок."},{"text":"Гена передал Серёже четверть своих шоколадок. У Гены осталось 3m − 3m/4, у Серёжи стало m + 3m/4."},{"text":"У Гены стало на 6 шоколадок больше, чем у Серёжи. Составим уравнение 3m − 3m/4 − 6 = m + 3m/4."},{"text":"Получаем m = 12. Сначала у Гены было 36 шоколадок, у Серёжи — 12. Разница составляла 24 шоколадки."}]},"30":{"steps":[{"text":"На 230 рублей можно купить не более 7 цветков первого типа, 5 цветков второго типа или 4 цветка третьего типа."},{"text":"При этом ни один из этих вариантов не стоит ровно 230 руб."},{"text":"Значит, букеты будут состоять из цветков нескольких типов."},{"text":"Возможные варианты: 1 · 30 + 5 · 40 = 230; 1 · 30 + 4 · 50 = 230; 2 · 30 + 3 · 40 + 1 · 50 = 230; 3 · 30 + 1 · 40 + 2 · 50 = 230; 5 · 30 + 2 · 40 = 230; 6 · 30 + 1 · 50 = 230; 2 · 40 + 3 · 50 = 230. Итого 7 вариантов букетов."},{"text":"Другие букеты не дадут в сумме ровно 230 руб."}]}}};
globalThis.KENGURU_GRADE_KEYS = {};
globalThis.KENGURU_GRADE_TITLES = {"2025":["Недостающая деталь мозаики","Число 2025 сзади","Числа в окошках билета","Наклейки на кубе","Начинки на пицце","Вода из пяти отверстий","Повороты шестиугольника","Цены на бургеры","Финиш шести бегунов","Книги на трёх полках","Забег трёх кенгуру","Числа в башне","Колёса удачи","Фигуры на белых клетках","Время пловцов","Периметр бумажного креста","Закрашенные цифры на карточках","Линия деления фигуры","Нули и единицы в таблице","Средние числа Кати и Лёши","Превращения фруктов","Отрезки через центр квадрата","Пять одинаковых частей","Разговор о днях недели","Крест из деталей","Блоки в равновесии","Суммы в соседних квадратах","Конструкции из трёх блоков","Две стопки шоколадок","Букеты за 230 рублей"]};
